"""Server-side validation logic for the registration wizard.

This module is intentionally written using only the Python standard library
so it can be imported and tested with a plain ``python3`` interpreter
without pulling in any Reflex/Web framework dependencies.
"""

from __future__ import annotations

from typing import Any, Dict


def _is_blank(value: Any) -> bool:
    """Return True when ``value`` is None, an empty string, or only whitespace."""
    if value is None:
        return True
    if isinstance(value, str):
        return value.strip() == ""
    # Booleans/ints/etc. are not considered "blank" for the blank-checks below
    # (the wizard code only passes strings for the blank-checked fields).
    return False


def _is_valid_email(value: Any) -> bool:
    """Return True if ``value`` is a valid email per the wizard's rules.

    Rules:
    * Must be a non-empty string (caller normally guards the blank case first).
    * Must contain a single ``@`` character.
    * The local part (before the ``@``) must be non-empty.
    * The domain part (after the ``@``) must contain at least one dot.
    """
    if not isinstance(value, str):
        return False
    if value == "":
        return False
    if value.count("@") != 1:
        return False
    local, _, domain = value.partition("@")
    if local == "":
        return False
    if "." not in domain or domain.startswith(".") or domain.endswith("."):
        return False
    if not all(part and part.strip(" ") for part in domain.split(".")):
        return False
    return True


def validate_step(step: int, data: Dict[str, Any]) -> Dict[str, str]:
    """Validate a single wizard step and return a dict of field -> error message.

    Parameters
    ----------
    step:
        ``1`` (Account), ``2`` (Security) or ``3`` (Confirmation).
    data:
        Mapping that may contain any of the wizard fields:
        ``email``, ``password``, ``confirm_password``, ``full_name``,
        ``accept_terms``.

    Returns
    -------
    dict
        Mapping from invalid field name to error message. An empty dict means
        the step is valid. Only the first failure per field is reported.
    """
    errors: Dict[str, str] = {}

    if step == 1:
        email = data.get("email", "")
        if _is_blank(email):
            errors["email"] = "Email is required"
        elif not _is_valid_email(email):
            errors["email"] = "Invalid email address"
    elif step == 2:
        password = data.get("password", "")
        confirm_password = data.get("confirm_password", "")

        # Password checks are evaluated in the required order; the first
        # failing rule wins so the user only sees one error at a time.
        if not isinstance(password, str) or len(password) < 8:
            errors["password"] = "Password must be at least 8 characters"
        elif not any(c.isupper() for c in password):
            errors["password"] = "Password must contain an uppercase letter"
        elif not any(c.islower() for c in password):
            errors["password"] = "Password must contain a lowercase letter"
        elif not any(c.isdigit() for c in password):
            errors["password"] = "Password must contain a digit"

        if confirm_password != password:
            errors["confirm_password"] = "Passwords do not match"
    elif step == 3:
        full_name = data.get("full_name", "")
        accept_terms = data.get("accept_terms", False)

        if _is_blank(full_name):
            errors["full_name"] = "Full name is required"
        if not accept_terms:
            errors["accept_terms"] = "You must accept the terms"
    else:
        raise ValueError(f"Unknown step: {step!r}; expected 1, 2 or 3")

    return errors


if __name__ == "__main__":
    # A tiny self-test that exercises the rules end-to-end.
    assert validate_step(1, {}) == {"email": "Email is required"}
    assert validate_step(1, {"email": "   "}) == {"email": "Email is required"}
    assert validate_step(1, {"email": "not-an-email"}) == {
        "email": "Invalid email address"
    }
    assert validate_step(1, {"email": "a@b"}) == {"email": "Invalid email address"}
    assert validate_step(1, {"email": "user@example.com"}) == {}

    assert validate_step(2, {"password": "short"}) == {
        "password": "Password must be at least 8 characters"
    }
    assert validate_step(
        2, {"password": "alllowercase1", "confirm_password": "alllowercase1"}
    ) == {"password": "Password must contain an uppercase letter"}
    assert validate_step(
        2, {"password": "ALLUPPERCASE1", "confirm_password": "ALLUPPERCASE1"}
    ) == {"password": "Password must contain a lowercase letter"}
    assert validate_step(
        2, {"password": "NoDigitsHere", "confirm_password": "NoDigitsHere"}
    ) == {"password": "Password must contain a digit"}
    assert validate_step(
        2, {"password": "GoodPass1", "confirm_password": "Different1"}
    ) == {"confirm_password": "Passwords do not match"}
    assert validate_step(
        2, {"password": "GoodPass1", "confirm_password": "GoodPass1"}
    ) == {}

    assert validate_step(3, {"full_name": "  ", "accept_terms": True}) == {
        "full_name": "Full name is required"
    }
    assert validate_step(3, {"full_name": "Jane Doe", "accept_terms": False}) == {
        "accept_terms": "You must accept the terms"
    }
    assert validate_step(3, {"full_name": "Jane Doe", "accept_terms": True}) == {}
    print("validators.py: self-test passed")

